#!/usr/bin/env python3
"""Fence every scaffold request/snapshot until a real adapter overrides it."""
import argparse
from pathlib import Path
from generate_mock_server_api import exports

ROOT = Path(__file__).resolve().parents[1]

def generate() -> str:
    lines = ['extends "res://scripts/net/mock_server.gd"',
             '# Generated by tools/generate_remote_boundary.py; do not edit.',
             '# Reuse presentation models, never inherited authoritative requests.', '']
    for row in exports():
        if row.kind != 'api' or not row.name.startswith(('try_', 'snapshot_')):
            continue
        name, arguments, kind = row.name, row.arguments, row.result
        lines.append('@warning_ignore("unused_parameter")')
        lines.append(f'func {name}({arguments})' + (f' -> {kind}' if kind else '') + ':')
        if name.startswith('snapshot_'):
            value = '[]' if kind.startswith('Array') else '{}'
            lines.append(f'\treturn {value}')
        elif kind == 'void':
            lines.append(f'\t_remote_notice("{name}")')
        elif kind == 'bool':
            lines += [f'\t_remote_notice("{name}")', '\treturn false']
        elif kind.startswith('Array'):
            lines += [f'\t_remote_notice("{name}")', '\treturn []']
        else:
            lines.append(f'\treturn _unsupported("{name}")')
        lines.append('')
    lines += ['func _unsupported(operation:String)->Dictionary:',
              '\treturn {"ok":false,"error":"unsupported_remote_operation","operation":operation,"actions":[{"type":"system_message","text":"真实服务器尚未接入此操作："+operation}]}',
              '', 'func _remote_notice(_operation:String)->void:pass', '']
    return '\n'.join(lines)

if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    target = ROOT / 'scripts/net/remote_boundary.gd'
    output = generate()
    if args.check:
        if target.read_text(encoding='utf-8') != output:
            raise SystemExit('Remote boundary is stale; regenerate it')
    else:
        target.write_text(output, encoding='utf-8')
